def gen(rng):
    def num(L):
        return str(rng.randint(10 ** (L - 1), 10 ** L - 1)) if L > 1 else str(rng.randint(1, 9))

    def fmt(pairs):
        return str(len(pairs)) + '\n' + ' '.join(p[0] for p in pairs) + '\n' + ' '.join(p[1] for p in pairs)

    tests = [fmt([('5', '5')]), fmt([('1', '9')]), fmt([('9', '1')]), fmt([('123', '321'), ('45', '54')]),
             fmt([('100', '999')]), fmt([('909', '190')]), fmt([('7', '7'), ('88', '88')]),
             fmt([('999999999', '111111111')]), fmt([('100000000', '999999999')])]
    for _ in range(30):
        n = rng.randint(1, 6)
        pairs = []
        for _ in range(n):
            L = rng.randint(1, 9)
            pairs.append((num(L), num(L)))
        tests.append(fmt(pairs))
    N = 10**5
    for mode in range(4):
        pairs = []
        for _ in range(N):
            L = 9 if mode < 2 else rng.randint(1, 9)
            if mode == 0:
                pairs.append(('1' + '0' * 8, '9' * 9))
            else:
                pairs.append((num(L), num(L)))
        tests.append(fmt(pairs))
    return tests

